import { 
  PlaneGeometry, 
  Mesh, 
  Vector2,
  Group
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  uniform,
  uv,
  texture,
  vec2,
  mul,
  add,
  clamp,
  textureSize
} from 'three/tsl';
import gsap from 'gsap';
import { Vector3 } from 'three';

export default function createNode(config, ctx) {
  const {
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {},
    bezier
  } = config;

  const imageUrl = assets.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = assets.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  // Load textures
  const mapTexture = ctx.textureLoader.load(imageUrl);
  const depthTexture = ctx.textureLoader.load(depthMapUrl);

  // Parallax mouse offset uniform
  const parallaxOffset = uniform(vec2(0.0, 0.0));

  // Build displacement node: read depth map red channel, scale, add parallax offset influence
  const depthValue = texture(depthTexture, uv()).x;
  const baseDisplacement = mul(depthValue, 0.15); // subtle height
  const parallaxDisplacement = add(baseDisplacement, 
    mul(parallaxOffset.x, 0.03).toVar()
  );
  // Ensure displacement doesn't go negative
  const clampedDisp = clamp(parallaxDisplacement, 0.0, 0.2);

  // Create geometry and material
  const geometry = new PlaneGeometry(2.5, 1.2, 64, 64);
  const material = new MeshBasicNodeMaterial({
    map: mapTexture,
    displacementMap: null, // we handle displacement via node
    displacementNode: clampedDisp,
    displacementScale: 1.0
  });

  const plane = new Mesh(geometry, material);
  plane.position.set(position[0], position[1], position[2]);
  plane.rotation.set(rotation[0], rotation[1], rotation[2]);
  plane.scale.set(scale[0], scale[1], scale[2]);

  // Wrap in group for future child elements (divider, text)
  const group = new Group();
  group.add(plane);

  // --- Interaction handlers ---
  const handlers = {};

  // Hover: rise-in preset
  let hoverTimeline = null;
  handlers.hover = (entering) => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(plane.position, {
      y: entering ? plane.position.y + 0.15 : plane.position.y,
      duration: 0.4,
      ease: 'power3.out',
      overwrite: true
    });
  };

  // Click: emit navigation event
  handlers.click = () => {
    // If data binding provided, navigate to checkout URL
    if (config.dataBindings && config.dataBindings.length > 0) {
      const binding = config.dataBindings[0];
      if (binding.source === 'trpc.checkout.begin.checkoutUrl' && binding.target === 'onClick.navigate') {
        // This would be handled by the framework; we just emit
      }
    }
    // Emit event for parent
    if (ctx.emit) {
      ctx.emit('hub-features.select', { node: group });
    }
  };

  // Parallax mouse move handler (updates uniform)
  handlers.mousemove = (mousePos) => {
    // mousePos is a normalized Vector2 [-1,1] relative to viewport
    const target = new Vector2(
      mousePos.x * 0.02,
      mousePos.y * 0.02
    );
    parallaxOffset.value.lerp(target, 0.1);
  };

  group.userData.handlers = handlers;

  // Cleanup
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
    depthTexture.dispose();
    // Remove from parent if needed
    if (group.parent) group.parent.remove(group);
  };

  return group;
}
